import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.dWYrTn1b.js";const p=JSON.parse(`{"title":"Judging a run","description":"How a run is judged, from the task's own account, from the simulator's ground truth, and by the program's checks, and where each verdict is written.","frontmatter":{"title":"Judging a run","description":"How a run is judged, from the task's own account, from the simulator's ground truth, and by the program's checks, and where each verdict is written."},"headers":[],"relativePath":"guide/advanced/judging-a-run.md","filePath":"guide/advanced/judging-a-run.md"}`),d={name:"guide/advanced/judging-a-run.md"};function r(n,e,i,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="judging-a-run" tabindex="-1">Judging a run <a class="header-anchor" href="#judging-a-run" aria-label="Permalink to &quot;Judging a run&quot;">​</a></h1><p>A run ends with two files under <code>run/</code>: what the robot says happened, and what the simulator saw.</p><h2 id="the-task-s-own-account" tabindex="-1">The task&#39;s own account <a class="header-anchor" href="#the-task-s-own-account" aria-label="Permalink to &quot;The task&#39;s own account&quot;">​</a></h2><p><code>run/task_result.json</code> is written by the task runner:</p><ul><li>the status: <code>success</code>, <code>failure</code>, <code>timeout</code>, <code>error</code> or <code>not_started</code>;</li><li>the start and end times, in simulation seconds;</li><li>one event per action, with its parameters, times and outcome;</li><li>the final pose the robot believes it has, and the distance its odometry measured.</li></ul><p>It is the robot&#39;s belief, as good as its localization and odometry.</p><h2 id="three-verdicts" tabindex="-1">Three verdicts <a class="header-anchor" href="#three-verdicts" aria-label="Permalink to &quot;Three verdicts&quot;">​</a></h2><p>While the task runs, the runner also records the robot&#39;s pose as the simulator publishes it, the joint states, and every bumper&#39;s reports. When the task ends it writes <code>run/evaluation.json</code> with three verdicts, each resting on different evidence:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Rests on</th><th>Fails when</th></tr></thead><tbody><tr><td><code>task</code></td><td>The task runner&#39;s status</td><td>The task did not succeed</td></tr><tr><td><code>physical</code></td><td>The simulator&#39;s pose alone</td><td>The robot ended away from its goal, or touched an obstacle</td></tr><tr><td><code>checks</code></td><td>Each check of the <code>.eval</code> file</td><td>A check&#39;s value left its bounds</td></tr></tbody></table><p>The physical verdict asks two questions:</p><ul><li><strong>Did the robot end near its goal?</strong> The last goal it navigated to, within twice the controller&#39;s goal tolerance. The controller stops on its own belief, and the ground truth differs from that belief by the localization error.</li><li><strong>Did it touch an obstacle?</strong> Its closest approach to any <code>Obstacle</code> over the run, measured between the collision shapes seen from above; within 5 mm is a touch.</li></ul><p>The three can disagree, and that is the point. A task that reports <code>success</code> while the robot stopped short of the goal, or brushed a box on the way, fails the physical verdict.</p><h2 id="how-checks-are-measured" tabindex="-1">How checks are measured <a class="header-anchor" href="#how-checks-are-measured" aria-label="Permalink to &quot;How checks are measured&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Checks</th><th>Read</th></tr></thead><tbody><tr><td><code>Check_vel</code>, <code>Check_acc</code>, <code>Check_jerk</code>, <code>Check_effort</code></td><td>The named wheel&#39;s joint states, every sample judged by magnitude</td></tr><tr><td><code>Check_distance</code>, <code>Check_clearance</code></td><td>The recorded poses and the planar shapes in <code>task/evaluation.json</code></td></tr><tr><td><code>Check_contact</code></td><td>A bumper&#39;s own reports; for any other part, the poses and shapes</td></tr><tr><td><code>Check_time</code></td><td>The task&#39;s duration</td></tr></tbody></table><p>A check with no samples to judge is <code>unknown</code>, never <code>pass</code>. Nothing is read from odometry or from Nav2.</p><h2 id="shapes" tabindex="-1">Shapes <a class="header-anchor" href="#shapes" aria-label="Permalink to &quot;Shapes&quot;">​</a></h2><p>The shapes the evaluation measures are the collision shapes the robot is simulated with, seen from above: the chassis and sensor collision boxes, each wheel as its diameter by its width, and each scene entity as its box or circle. A part without a collision box counts as a point, which is one more reason to declare one.</p>',17)])])}const m=t(d,[["render",r]]);export{p as __pageData,m as default};
